// readLoginURLActionFromTTY takes ownership of tty and closes it on every path.
// Bubble Tea handles raw mode, escape-sequence decoding, and terminal
// restoration; cancellation is translated into a Quit here rather than handed to
// Bubble Tea as a context. If the terminal cannot provide single-key input,
// disable key actions.
func readLoginURLActionFromTTY(ctx context.Context, errW io.Writer, tty *os.File) (loginURLAction, error) {
	// This function owns tty on every path. That is only safe because shutdown
	// is driven by Quit rather than by context cancellation — see below.
	defer func() { _ = tty.Close() }()

	if !interactive.IsTerminalReader(tty) {
		return loginURLNone, nil
	}

	// Nothing to read once we are already cancelled, and returning here means no
	// program — hence no input reader — is started at all.
	if err := ctx.Err(); err != nil {
		return loginURLNone, fmt.Errorf("interrupted: %w", err)
	}

	program := tea.NewProgram(
		loginURLActionModel{},
		tea.WithInput(tty),
		tea.WithOutput(io.Discard),
		tea.WithoutSignalHandler(),
	)

	// Deliberately NOT tea.WithContext(ctx). A context-cancelled Run is a
	// *killed* Run (Run computes `killed` from externalCtx.Err() || ctx.Err() ||
	// err != nil), and shutdown(kill=true) skips waitForReadLoop() before
	// closing its cancelreader. That leaves two descriptors being closed under a
	// live reader: tty, and — inside cancelreader itself — its own cancel-signal
	// pipe, whose Fd() the reader reads on wake. Both are data races the detector
	// fails the whole package for, and the second one is upstream, so no amount
	// of care here would have avoided it.
	//
	// Quit instead delivers a QuitMsg, which eventLoop returns with a nil error,
	// so `killed` stays false and shutdown joins the read loop before closing
	// anything. Nothing is left holding tty afterwards, which is what lets the
	// close above be unconditional.
	quitDone := make(chan struct{})
	defer close(quitDone)
	go func() {
		select {
		case <-ctx.Done():
			// Send is safe here even after Run returns: shutdown cancels the
			// program's own context, which Send selects on.
			program.Quit()
		case <-quitDone:
		}
	}()

	finalModel, err := program.Run()
	if ctx.Err() != nil {
		return loginURLNone, fmt.Errorf("interrupted: %w", ctx.Err())

